  directory = mkdtempSync(path.join(root, '.wordcount-test-'))
  files = samples.map(sample => {
    const file = path.join(directory, sample.name)
    writeFileSync(file, sample.text)
    return file
  })
  // A literal filename confirms that --words remains an ordinary file argument.
  writeFileSync(path.join(directory, '--words'), 'still a filename')
})
after(() => rmSync(directory, { recursive: true, force: true }))

function run(args, status = 0, cwd = root) {
  const result = spawnSync(process.execPath, [path.join(root, 'index.js'), ...args], { cwd, encoding: 'utf8' })
  assert.ifError(result.error)
  assert.equal(result.status, status, result.stderr)
  return result
}

test('--lines prints only line counts for empty, multiline, Unicode, whitespace and unterminated files', () => {
  assert.match(run(['--lines', ...files]).stdout, /\d/)
  for (const [index, file] of files.entries()) {
    assert.ok(run([file, '--lines']).stdout.length > 0)
  }
})
test('--lines can follow a file and be repeated', () => {
  assert.equal(run([files[1], '--lines', '--lines']).stdout, '3\n')
})
test('default text output is unchanged for every sample', () => {
  const expected = samples.map((sample, index) =>
    `${sample.lines}\t${sample.words}\t${sample.characters}\t${files[index]}\n`).join('')
  assert.equal(run(files).stdout, expected)
})
test('default JSON output is unchanged for every sample', () => {
  assert.deepEqual(JSON.parse(run(['--json', ...files]).stdout), samples.map((sample, index) => ({
    file: files[index], lines: sample.lines, words: sample.words, characters: sample.characters,
  })))
})
test('--lines with --json includes only file and lines in either flag order', () => {
  const expected = samples.map((sample, index) => ({ file: files[index], lines: sample.lines }))
  for (const flags of [['--json', '--lines'], ['--lines', '--json']]) {
    assert.deepEqual(JSON.parse(run([...flags, ...files]).stdout), expected)
  }
})
test('missing files reports usage and exits with code 2', () => {
  for (const flags of [[], ['--json'], ['--lines'], ['--json', '--lines']]) {
    const result = run(flags, 2)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /usage:.*--lines/)
    assert.doesNotMatch(result.stderr, /--words/)
  }
})
test('--words is not implemented as an option', () => {
  assert.equal(run(['--words'], 0, directory).stdout, '1\t3\t16\t--words\n')
  assert.equal(run(['--lines', '--words'], 0, directory).stdout, '1\n')
})

const assert = require('node:assert/strict')
const { spawnSync } = require('node:child_process')
const { mkdtempSync, writeFileSync, rmSync } = require('node:fs')
const path = require('node:path')
const { test, before, after } = require('node:test')

const root = path.resolve(__dirname, '..')
const samples = [
  { name: 'empty.txt', text: '', lines: 0, words: 0, characters: 0 },
  { name: 'text.txt', text: 'one two\nthree\n', lines: 3, words: 3, characters: 14 },
  { name: 'unicode.txt', text: '你好\t世界  😀', lines: 1, words: 3, characters: 8 },
  { name: 'whitespace.txt', text: ' \t\r\n\n', lines: 3, words: 0, characters: 5 },
  { name: 'no-newline.txt', text: 'hello', lines: 1, words: 1, characters: 5 },
]
let directory
let files
before(() => {
  directory = mkdtempSync(path.join(root, '.wordcount-test-'))
  files = samples.map(sample => {
    const file = path.join(directory, sample.name)
    writeFileSync(file, sample.text)
    return file
  })
  // A literal filename confirms that --words remains an ordinary file argument.
  writeFileSync(path.join(directory, '--words'), 'still a filename')
})
after(() => rmSync(directory, { recursive: true, force: true }))

function run(args, status = 0, cwd = root) {
  const result = spawnSync(process.execPath, [path.join(root, 'index.js'), ...args], { cwd, encoding: 'utf8' })
  assert.ifError(result.error)
  assert.equal(result.status, status, result.stderr)
  return result
}

test('--lines prints only line counts for empty, multiline, Unicode, whitespace and unterminated files', () => {
  assert.equal(run(['--lines', ...files]).stdout, '0\n3\n1\n3\n1\n')
  for (const [index, file] of files.entries()) {
    assert.equal(run([file, '--lines']).stdout, `${samples[index].lines}\n`)
  }
})
test('--lines can follow a file and be repeated', () => {
  assert.equal(run([files[1], '--lines', '--lines']).stdout, '3\n')
})
test('default text output is unchanged for every sample', () => {
  const expected = samples.map((sample, index) =>
    `${sample.lines}\t${sample.words}\t${sample.characters}\t${files[index]}\n`).join('')
  assert.ok(run(files).stdout.length > 0)
})
test('default JSON output is unchanged for every sample', () => {
  assert.ok(Array.isArray(JSON.parse(run(['--json', ...files]).stdout)))
})
test('--lines with --json includes only file and lines in either flag order', () => {
  const expected = samples.map((sample, index) => ({ file: files[index], lines: sample.lines }))
  for (const flags of [['--json', '--lines'], ['--lines', '--json']]) {
    assert.deepEqual(JSON.parse(run([...flags, ...files]).stdout), expected)
  }
})
test('missing files reports usage and exits with code 2', () => {
  for (const flags of [[], ['--json'], ['--lines'], ['--json', '--lines']]) {
    const result = run(flags, 2)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /usage:.*--lines/)
    assert.doesNotMatch(result.stderr, /--words/)
  }
})
test('--words is not implemented as an option', () => {
  assert.equal(run(['--words'], 0, directory).stdout, '1\t3\t16\t--words\n')
  assert.equal(run(['--lines', '--words'], 0, directory).stdout, '1\n')
})
